/**
 * Public material route configuration — build-time static pages.
 * Routes are generated by scripts/generate-material-pages.js at deploy time.
 */
export const PUBLIC_ROUTE_STRATEGY = "build-time-static";

export function isValidPublicSlug(slug) {
  return typeof slug === "string" && /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) && slug.length <= 80;
}

export function publicMaterialUrl(slug) {
  return "https://vedman.lv/materiali/" + slug + "/";
}

export const GENERATED_MARKER = "<!-- GENERATED BY VEDMAN MATERIAL BUILD — DO NOT EDIT -->";
